INSERT INTO DimCompany (SK_CompanyID, CompanyID, Status, Name, Industry, SPrating, isLowGrade, CEO, Description, FoundingDate, AddressLine1, AddressLine2, PostalCode, City, StateProv, Country, IsCurrent, BatchID, EffectiveDate, EndDate) SELECT CAST(ROW_NUMBER() OVER (ORDER BY CompanyID, EffectiveDate) AS INT) AS SK_CompanyID, CAST(CompanyID AS INT) AS CompanyID, CAST(Status AS TEXT) AS Status, CAST(Name AS TEXT) AS Name, CAST(Industry AS TEXT) AS Industry, CAST(SPrating AS TEXT) AS SPrating, CAST(isLowGrade AS BOOLEAN) AS isLowGrade, CAST(CEO AS TEXT) AS CEO, CAST(Description AS TEXT) AS Description, CAST(FoundingDate AS DATE) AS FoundingDate, CAST(AddressLine1 AS TEXT) AS AddressLine1, CAST(AddressLine2 AS TEXT) AS AddressLine2, CAST(PostalCode AS TEXT) AS PostalCode, CAST(City AS TEXT) AS City, CAST(StateProv AS TEXT) AS StateProv, CAST(Country AS TEXT) AS Country, CAST(CASE WHEN LEAD(EffectiveDate) OVER (PARTITION BY CompanyID ORDER BY EffectiveDate ASC) IS NULL THEN TRUE ELSE FALSE END AS BOOLEAN) AS IsCurrent, CAST(1 AS DECIMAL(5, 0)) AS BatchID, CAST(EffectiveDate AS DATE) AS EffectiveDate, CAST(COALESCE(LEAD(EffectiveDate) OVER (PARTITION BY CompanyID ORDER BY EffectiveDate ASC), CAST('9999-12-31' AS DATE)) AS DATE) AS EndDate FROM (SELECT CIK AS CompanyID, CASE WHEN TRIM(CMP.CompanyName) = '' THEN NULL ELSE CMP.CompanyName END AS Name, CAST(CMP.SPrating AS TEXT) AS SPrating, CASE WHEN TRIM(CMP.CEOname) = '' THEN NULL ELSE CMP.CEOname END AS CEO, CASE WHEN TRIM(CMP.Description) = '' THEN NULL ELSE CMP.Description END AS Description, CAST(TRY_STRPTIME(FoundingDate, '%Y%m%d') AS DATE) AS FoundingDate, CASE WHEN TRIM(CMP.AddrLine1) = '' THEN NULL ELSE CMP.AddrLine1 END AS AddressLine1, CASE WHEN TRIM(CMP.AddrLine2) = '' THEN NULL ELSE CMP.AddrLine2 END AS AddressLine2, CASE WHEN TRIM(CMP.PostalCode) = '' THEN NULL ELSE CMP.PostalCode END AS PostalCode, CASE WHEN TRIM(CMP.City) = '' THEN NULL ELSE CMP.City END AS City, CASE WHEN TRIM(CMP.StateProvince) = '' THEN NULL ELSE CMP.StateProvince END AS StateProv, CASE WHEN TRIM(CMP.Country) = '' THEN NULL ELSE CMP.Country END AS Country, S.ST_NAME AS Status, I.IN_NAME AS Industry, CASE WHEN CMP.SPrating IN ('AAA', 'AA', 'A', 'BBB', 'BB', 'B', 'CCC', 'CC', 'C', 'D', 'AA+', 'A+', 'BBB+', 'BB+', 'B+', 'CCC+', 'AA-', 'A-', 'BBB-', 'BB-', 'B-', 'CCC-') THEN (CASE WHEN CMP.SPrating LIKE 'A%' OR CMP.SPrating LIKE 'BBB%' THEN FALSE ELSE TRUE END) END AS isLowGrade, CAST(STRPTIME(PTS, '%Y%m%d-%H%M%S') AS DATE) AS EffectiveDate FROM Source.FinwireCMP AS CMP, Source.StatusType AS S, Source.Industry AS I WHERE CMP.Status = S.ST_ID AND CMP.IndustryID = I.IN_ID) AS c;
